        mov     ax, [readKey__ret]
        mov     [browse__key], ax
; ---- ch = u8( key & 0xFF )
        and     ax, 255
        mov     [browse__ch], al            ; u16 -> u8, no widening
; ---- scan = u8( key >> 8 )
        mov     ax, [browse__key]
        mov     cl, 8                       ; 8086 has no shift-by-immediate
        shr     ax, cl                      ; unsigned >>
        mov     [browse__scan], al          ; u16 -> u8, no widening
; ---- if ( ch == keyEsc ) return
        mov     al, [browse__ch]
        cmp     al, 27                      ; byte operands, no widening
        jne     .L366                       ; unsigned ==
        ret
.L366:
; ---- if ( ch != 0 && ch != 0xE0 ) continue
        mov     al, [browse__ch]
        test    al, al
        je      .L369                       ; unsigned !=
        mov     al, [browse__ch]
        cmp     al, 224                     ; byte operands, no widening
        je      .L369                       ; unsigned !=
        jmp     .L361
.L369:
; ---- if ( scan == keyRight ) {
        mov     al, [browse__scan]
        cmp     al, 77                      ; byte operands, no widening
        jne     .L373                       ; unsigned ==
; ---- cur = cur + 1 == flatCount ? 0 : cur + 1
        mov     ax, [browse__cur]
        inc     ax
        mov     bx, [flatCount]
        cmp     ax, bx
        jne     .L376                       ; unsigned ==
        xor     ax, ax                      ; 0
        jmp     .L377
.L376:
        mov     ax, [browse__cur]
        inc     ax
.L377:
        mov     [browse__cur], ax
        jmp     .L374
.L373:
; ---- } else if ( scan == keyLeft ) {
        mov     al, [browse__scan]
        cmp     al, 75                      ; byte operands, no widening
        jne     .L379                       ; unsigned ==
; ---- cur = cur == 0 ? flatCount - 1 : cur - 1
        mov     ax, [browse__cur]
        test    ax, ax
        jne     .L382                       ; unsigned ==
        mov     ax, [flatCount]
        dec     ax
        jmp     .L383
.L382:
        mov     ax, [browse__cur]
        dec     ax
.L383:
        mov     [browse__cur], ax
        jmp     .L380
.L379:
; ---- } else if ( scan == keyPgDn ) {
        mov     al, [browse__scan]
        cmp     al, 81                      ; byte operands, no widening
        jne     .L385                       ; unsigned ==
; ---- cur = ( cur + 10 ) % flatCount
        mov     ax, [browse__cur]
        add     ax, 10
        mov     bx, [flatCount]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     ax, dx                      ; remainder
        mov     [browse__cur], ax
        jmp     .L386
.L385:
; ---- } else if ( scan == keyPgUp ) {
        mov     al, [browse__scan]
        cmp     al, 73                      ; byte operands, no widening
        jne     .L388                       ; unsigned ==
; ---- cur = ( cur + flatCount - 10 % flatCount ) % flatCount
        mov     ax, [browse__cur]
        mov     bx, [flatCount]
        add     ax, bx
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, 10
        mov     bx, [flatCount]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     ax, dx                      ; remainder
        mov     bx, ax
        pop     ax
        sub     ax, bx
        mov     bx, [flatCount]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     ax, dx                      ; remainder
        mov     [browse__cur], ax
.L388:
.L386:
.L380:
.L374:
.L361:
        jmp     .L360
.L362:
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

int16:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

